enum level { LOW, MID, HIGH };

int score(enum level l) {
    int s = 0;
    switch (l) {
        case HIGH:
            s += 100;
            /* fall through */
        case MID:
            s += 10;
            /* fall through */
        case LOW:
            s += 1;
    }
    return s;
}

